# ====== HTTP-СЕРВЕР ======
app = Flask(__name__)
CORS(app)  # Разрешаем фронтенду обращаться к бэкенду

# Строим индекс ОДИН РАЗ при запуске сервера
print("🔨 Строим индекс BM25...")
bm25_index = build_index(docs)
print(f"✅ Готово! Документов: {bm25_index['N']}, средняя длина: {bm25_index['avgdl']:.2f}")


@app.route('/ask', methods=['POST'])
def ask():
    """Эндпоинт для фронтенда: принимает вопрос, возвращает ответ + источники."""
    data = request.json
    question = data.get('question', '').strip()

    if not question:
        return jsonify({"error": "Вопрос не задан"}), 400

    # Запускаем RAG
    state = run_rag(
        question=question,
        docs=docs,
        bm25_index=bm25_index,
        k=3
    )

    # Формируем список источников
    sources_list = []
    if state.get("sources"):
        for s in state["sources"]:
            sources_list.append({
                "id": s["id"],
                "schema": s["schema"]
            })

    return jsonify({
        "answer": state["answer"],
        "sources": sources_list
    })


if __name__ == '__main__':
    print("\n🚀 Сервер запущен: http://127.0.0.1:5000")
    print("📡 Эндпоинт: POST /ask\n")
    app.run(host='127.0.0.1', port=5000, debug=True)